public class Editor {
    private StringBuilder content = new StringBuilder();
    private int cursor;

    public void type(String text) {
        content.insert(cursor, text);
        cursor += text.length();
    }

    // Memento is private: only Editor can see inside.
    public final class Snapshot {
        private final String contentCopy;
        private final int cursorCopy;
        private Snapshot(String c, int cursor) {
            this.contentCopy = c;
            this.cursorCopy = cursor;
        }
    }

    public Snapshot save() {
        // Defensive copy: String is immutable, so this is a true snapshot.
        // If content held mutable refs, deep-copy them here.
        return new Snapshot(content.toString(), cursor);
    }

    public void restore(Snapshot s) {
        if (s == null) throw new IllegalArgumentException("null snapshot");
        this.content = new StringBuilder(s.contentCopy);
        // Re-clamp: invariants may have tightened since snapshot was taken.
        this.cursor = Math.min(s.cursorCopy, content.length());
    }
}

public class UndoManager {
    private final Deque<Editor.Snapshot> undo = new ArrayDeque<>();
    private final Deque<Editor.Snapshot> redo = new ArrayDeque<>();
    private final int limit;
    public UndoManager(int limit) { this.limit = limit; }

    public void checkpoint(Editor e) {
        undo.push(e.save());
        redo.clear(); // new branch invalidates redo; standard trade-off
        while (undo.size() > limit) undo.removeLast(); // oldest dies first
    }
    public void undo(Editor e) {
        if (undo.isEmpty()) return;
        redo.push(e.save()); // save present before rolling back
        e.restore(undo.pop());
    }
    public void redo(Editor e) {
        if (redo.isEmpty()) return;
        undo.push(e.save());
        e.restore(redo.pop());
    }
}
